-- Move existing wine text into four independent editable Details fields.
begin;
create temporary table wine_details_patch(id text primary key,before_payload jsonb,patch jsonb) on commit drop;
DO $$ BEGIN
if (select count(*) from public.academy_content c join wine_details_patch w using(id) where c.kind='menu' and c.payload->>'category'='wine')<>51 then raise exception 'Wine inventory changed';end if;
if exists(select 1 from public.academy_content c join wine_details_patch w using(id) where c.payload<>w.before_payload and c.payload<>w.before_payload||w.patch) then raise exception 'Concurrent menu edit; refresh snapshot';end if;
END $$;
create temporary table wine_details_before on commit drop as select c.* from public.academy_content c join wine_details_patch w using(id);
update public.academy_content c set payload=c.payload||w.patch,updated_at=now() from wine_details_patch w where c.id=w.id and c.payload is distinct from c.payload||w.patch;
DO $$ BEGIN
if exists(select 1 from public.academy_content c join wine_details_before b using(id) join wine_details_patch w using(id) where c.payload<>w.before_payload||w.patch or (to_jsonb(c)-'payload'-'updated_at')<>(to_jsonb(b)-'payload'-'updated_at')) then raise exception 'Unexpected wine update';end if;
END $$;
commit;
select payload->>'brand' brand,count(*) cards,count(*) filter(where length(payload->>'styleDescription')>0 and length(payload->>'tastingNotes')>0 and length(payload->>'gastronomy')>0 and length(payload->>'productionMethod')>0 and payload->>'description' not like '%Гастрономия:%') completed from public.academy_content where kind='menu' and payload->>'category'='wine' group by 1 order by 1;
